@startuml

abstract class Employee {
  + ssNo : int
  + name : string
  + email : string
}

class AdministrativeEmployee extends Employee {}

class ResearchAssistant extends Employee {
  + fieldOfStudy : string
}

class Lecturer extends ResearchAssistant {}

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Project {
  + name : string
  + start : date
  + end : date
}

class Course {
  + id : int
  + name : string
  + weeklyDuration : float
}

class Participation {
  + hours : int
}

Faculty "1" *-- "1..*" Institute
Faculty "1" -- "0..1" Employee : headed by
Employee "1" -- "*" AdministrativeEmployee
Employee "1" -- "*" ResearchAssistant
ResearchAssistant "1..*" -- "1..*" Institute
ResearchAssistant "1" -- "*" Participation
Participation "*" -- "1" Project
Lecturer "1..*" -- "*" Course : teaches

@enduml

